/**
 * Isometric room, adapted from "Indoor plants" by Storyset. The original is a
 * single-accent illustration; this is recoloured onto a warm palette and wired
 * up so the floor lamp is the site's dark mode switch.
 */

// The shade keeps its ochre when switched off, just dimmed — the site opens in
// dark mode, and going grey there would read as a different lamp.
const SHADE_LIT = '#DBA24C';
const SHADE_OFF = '#9c7a45';

/**
 * The cat is scaled down and nudged up the rug from where Storyset had it, to
 * clear the front edge for the seated figure. Derived from its untransformed
 * centre of (268.2, 384.9): e = cx - s * 268.2, f = cy - s * 384.9.
 */
const CAT_TRANSFORM = 'matrix(.7 0 0 .7 27.3 82.6)';

const GLOW = '#ffd98a';

/** The shade body, also masked over the glow so the bulb stays hidden under it. */
const SHADE_OUTLINE =
  'm263.8 102.7 12.6-32h28.3l12.6 32c1.8 5-.7 10.5-7.4 14.4a43 43 0 0 1-38.6 0c-6.8-4-9.3-9.3-7.5-14.4';

/** Shortens the lamp: the head drops by this much and the pole gives up the same. */
const LAMP_DROP = 45;
const SHADE_SHIFT = `translate(0 ${LAMP_DROP})`;
const POLE_PATH = `M288.5 ${112 + LAMP_DROP}h4.1v${(194.7 - LAMP_DROP).toFixed(
  1
)}a1 1 0 0 1-.6 1 3 3 0 0 1-2.9 0 1 1 0 0 1-.6-1Z`;

/**
 * Centred on the shade's bottom rim and wider than it is tall, so the light
 * pools downward and outward instead of ringing the lamp head. The mask cuts
 * the bright core away, leaving only what spills out from underneath.
 */
const GLOW_SHAPE = { cx: 290.8, cy: 122 + LAMP_DROP, rx: 122, ry: 84 };

/**
 * Seats the tree in the tall plant's place for the season: same centre line,
 * standing on the floor shadow the plant already casts, and a little taller
 * than it was, since a tree earns the height. The width follows the artwork's
 * own proportions so it fills the box rather than sitting letterboxed in it.
 */
const TREE_FOOT = 401;
const TREE_HEIGHT = 196;
const TREE = {
  x: 75.2 - (TREE_HEIGHT * TREE_ASPECT) / 2,
  y: TREE_FOOT - TREE_HEIGHT,
  width: TREE_HEIGHT * TREE_ASPECT,
  height: TREE_HEIGHT,
};

