      {/*
        Drawn after the cabinet so the light spills across it rather than being
        clipped behind it, and non-interactive so it doesn't steal clicks or
        hover from the lamp itself.
      */}
      <g
        id="lamp-glow"
        aria-hidden="true"
        opacity={lampIsLit ? 1 : 0}
        style={{ transition: 'opacity 400ms', pointerEvents: 'none' }}
      >
        <defs>
          {/* objectBoundingBox units, so the falloff matches the ellipse */}
          {/* a long, shallow ramp so the light reads as haze rather than a bulb */}
          <radialGradient id="lamp-glow-fade">
            <stop offset="0" stopColor={GLOW} stopOpacity="0.38" />
            <stop offset="0.35" stopColor={GLOW} stopOpacity="0.26" />
            <stop offset="0.7" stopColor={GLOW} stopOpacity="0.11" />
            <stop offset="1" stopColor={GLOW} stopOpacity="0" />
          </radialGradient>
          <mask id="lamp-glow-mask">
            <rect
              x={GLOW_SHAPE.cx - GLOW_SHAPE.rx}
              y={GLOW_SHAPE.cy - GLOW_SHAPE.ry}
              width={GLOW_SHAPE.rx * 2}
              height={GLOW_SHAPE.ry * 2}
              fill="#fff"
            />
            <path d={SHADE_OUTLINE} fill="#000" transform={SHADE_SHIFT} />
          </mask>
        </defs>
        <ellipse
          {...GLOW_SHAPE}
          fill="url(#lamp-glow-fade)"
          mask="url(#lamp-glow-mask)"
        />
      </g>
